#include "output/fb_writer.h"

#include <string>
#include <vector>

#include "output/json_writer.h"  // kEnvelopeSchemaVersion
#include "ovt/version.h"
#include "ovt_model_generated.h"  // generated by flatc from core/schema/ovt_model.fbs (WI-0.083)

namespace ovt::cli {

namespace {

ovt::fb::Severity severity_of(const std::string& name) {
  if (name == "Info") {
    return ovt::fb::Severity::Info;
  }
  if (name == "Warning") {
    return ovt::fb::Severity::Warning;
  }
  if (name == "Fatal") {
    return ovt::fb::Severity::Fatal;
  }
  return ovt::fb::Severity::Error;
}

const char* c_str_or_null(const std::string& s) {
  return s.empty() ? nullptr : s.c_str();
}

}  // namespace

flatbuffers::DetachedBuffer build_envelope_record(const Envelope& env, std::uint32_t record_count) {
  flatbuffers::FlatBufferBuilder fbb(1024);
  std::vector<flatbuffers::Offset<ovt::fb::Diagnostic>> diags;
  diags.reserve(env.diagnostics.size());
  for (const Diagnostic& d : env.diagnostics) {
    const ovt::fb::BitSpan span = d.span ? ovt::fb::BitSpan(d.span->first, d.span->second) : ovt::fb::BitSpan();
    diags.push_back(ovt::fb::CreateDiagnosticDirect(fbb, severity_of(d.severity), d.code.c_str(), d.message.c_str(),
                                                    d.span ? &span : nullptr, c_str_or_null(d.spec_ref)));
  }
  const std::string status(exit_code_name(env.status));
  const auto root = ovt::fb::CreateCliEnvelopeDirect(
      fbb, ovt_version_string(), kEnvelopeSchemaVersion, env.command.c_str(),
      env.input ? env.input->path.c_str() : nullptr, env.input ? env.input->size_bytes : 0,
      env.input ? &env.input->source_hash : nullptr, record_count, &diags, status.c_str());
  fbb.FinishSizePrefixed(root, kEnvelopeIdentifier.data());
  return fbb.Release();
}

bool is_size_prefixed_record(std::span<const std::uint8_t> record) noexcept {
  // prefix (4) + root offset (4) + identifier (4)
  constexpr std::size_t kMinSize = 3 * sizeof(flatbuffers::uoffset_t);
  if (record.size() < kMinSize) {
    return false;
  }
  const auto prefix = flatbuffers::ReadScalar<flatbuffers::uoffset_t>(record.data());
  return prefix == record.size() - sizeof(flatbuffers::uoffset_t);
}

bool FbStreamWriter::write_bytes(std::span<const std::uint8_t> bytes) {
  if (std::fwrite(bytes.data(), 1, bytes.size(), out_) != bytes.size()) {
    failed_ = true;
  }
  return !failed_;
}

bool FbStreamWriter::write_record(std::span<const std::uint8_t> record) {
  if (!is_size_prefixed_record(record)) {
    return false;
  }
  if (!magic_written_) {
    magic_written_ = true;
    write_bytes(kFbStreamMagic);
  }
  return write_bytes(record);
}

bool FbStreamWriter::finish() {
  if (!magic_written_) {
    magic_written_ = true;
    write_bytes(kFbStreamMagic);
  }
  return std::fflush(out_) == 0 && !failed_;
}

}  // namespace ovt::cli
